-- exec_board rows carry generated uuids, so to stay re-runnable we remove the
-- seeded members by name first (members added via the admin panel are left alone).
delete from public.exec_board where name in
('Ahmad Raza', 'Fatima Noor', 'Hamza Malik', 'Zainab Akhtar', 'Bilal Shah',
 'Ayesha Kanwal', 'Usman Tariq', 'Mahnoor Khan', 'Hassan Qureshi', 'Iqra Yousaf');


